const SIZE = 10;
const GOAL = 300;
const MAX_MOVES = 24;
const propertyList = [
  { id: 11, name: 'Moss Lane', price: 45, rent: 14, color: '#91ad64' },
  { id: 18, name: 'Pine Street', price: 60, rent: 18, color: '#78a584' },
  { id: 24, name: 'Market Row', price: 75, rent: 24, color: '#d3a15e' },
  { id: 37, name: 'The Old Steps', price: 55, rent: 17, color: '#bc8dba' },
  { id: 42, name: 'Willow Walk', price: 65, rent: 20, color: '#81a6b0' },
  { id: 53, name: 'Clover Court', price: 50, rent: 16, color: '#a2b75e' },
  { id: 67, name: 'Lantern Square', price: 80, rent: 26, color: '#d58668' },
  { id: 76, name: 'Juniper Way', price: 70, rent: 22, color: '#718eb2' },
  { id: 86, name: 'Little Harbor', price: 85, rent: 28, color: '#d39c5f' },
  { id: 95, name: 'Sunbeam Terrace', price: 65, rent: 20, color: '#cf8277' }
];
const stairPairs = [[13, 82], [29, 64]];
const coinSeed = [27, 45, 83, 16, 58, 34, 91, 9, 65, 21, 49, 3];
const directions = { up: [-1, 0], down: [1, 0], left: [0, -1], right: [0, 1] };
const opposite = { up: 'down', down: 'up', left: 'right', right: 'left' };
const $ = (id) => document.getElementById(id);
const board = $('board');
let cells = [];
let state;
let toastTimer;

function freshState() {
  return {
    started: false, finished: false, won: false, cash: 120, moves: 0,
    snake: [72, 71, 70], direction: 'right', coins: new Set(coinSeed),
    owned: new Set(), pending: null
  };
}
function propertyAt(id) { return propertyList.find((p) => p.id === id); }
function stairMate(id) {
  for (const pair of stairPairs) if (pair.includes(id)) return pair[0] === id ? pair[1] : pair[0];
  return null;
}
function setupBoard() {
  board.innerHTML = '';
  cells = [];
  for (let id = 0; id < SIZE * SIZE; id++) {
    const cell = document.createElement('div');
    cell.className = 'cell';
    cell.setAttribute('role', 'gridcell');
    cell.dataset.index = String(id + 1).padStart(2, '0');
    board.appendChild(cell);
    cells.push(cell);
  }
}
function updateBoard() {
  const snakeSet = new Set(state.snake);
  const owned = state.owned;
  cells.forEach((cell, id) => {
    const property = propertyAt(id);
    const isStair = stairMate(id) !== null;
    cell.className = 'cell';
    cell.removeAttribute('aria-label');
    cell.innerHTML = '';
    if (property) {
      cell.classList.add('property');
      cell.style.setProperty('--tile-color', property.color);
      if (owned.has(id)) cell.classList.add('owned');
      cell.innerHTML = `<span class="property-band"></span><span class="tile-icon">${owned.has(id) ? '⌂' : '＋'}</span><span class="cell-label">${property.name}</span>`;
      cell.setAttribute('aria-label', `${property.name}, ${owned.has(id) ? 'yours' : `for sale, $${property.price}`}`);
    } else if (isStair) {
      cell.classList.add('stair');
      cell.innerHTML = '<span class="tile-icon">↗</span>';
      cell.setAttribute('aria-label', 'Stairway');
    } else if (state.coins.has(id)) {
      cell.classList.add('coin');
      cell.innerHTML = '<span class="tile-icon">✦</span>';
      cell.setAttribute('aria-label', 'Loose change');
    } else {
      cell.setAttribute('aria-label', `City square ${id + 1}`);
    }
    if (snakeSet.has(id)) {
      cell.classList.add('snake-on-tile');
      const segment = document.createElement('span');
      segment.className = `snake-segment${id === state.snake[0] ? ` snake-head dir-${state.direction}` : ''}`;
      cell.appendChild(segment);
    }
  });
}
function updateUI() {
  $('cash-value').textContent = state.cash;
  $('turn-value').textContent = Math.max(0, MAX_MOVES - state.moves);
  $('move-label').innerHTML = `MOVE <b>${String(Math.min(state.moves + 1, MAX_MOVES)).padStart(2, '0')}</b> <i>/ ${MAX_MOVES}</i>`;
  $('owned-count').textContent = state.owned.size;
  const percent = Math.min(100, Math.round(state.cash / GOAL * 100));
  $('goal-percent').textContent = `${percent}%`;
  $('goal-progress-fill').style.width = `${percent}%`;
  $('cash-note').textContent = state.cash >= GOAL ? 'A city of your own!' : state.cash > 200 ? 'Looking like a local tycoon' : state.cash > 120 ? 'Your pockets are getting heavier' : 'A modest little start';
  const card = $('purchase-card');
  card.classList.toggle('hidden', !state.pending);
  $('deal-card').classList.toggle('hidden', Boolean(state.pending));
  if (state.pending) {
    const p = state.pending;
    $('purchase-name').textContent = p.name;
    $('purchase-price').textContent = `$${p.price}`;
    $('purchase-rent').textContent = `$${p.rent}`;
    $('purchase-color').style.background = p.color;
    $('buy-button').disabled = state.cash < p.price;
    $('buy-button').style.opacity = state.cash < p.price ? '.48' : '1';
  }
  updateBoard();
}
function setEvent(kicker, message, icon = '✦') {
  $('event-kicker').textContent = kicker;
  $('event-message').textContent = message;
  $('event-icon').textContent = icon;
}
function showToast(message) {
  const toast = $('toast');
  toast.textContent = message;
  toast.classList.add('show');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => toast.classList.remove('show'), 1650);
}
function setOverlay(title, message, button, icon = '↗') {
  const overlay = $('start-overlay');
  overlay.querySelector('.overlay-icon').textContent = icon;
  overlay.querySelector('h2').textContent = title;
  overlay.querySelector('p').innerHTML = message;
  $('start-button').innerHTML = `${button} <span>→</span>`;
  overlay.classList.remove('hidden');
}
function startGame() {
  if (state.started && !state.finished) return;
  if (state.finished) state = freshState();
  state.started = true;
  $('start-overlay').classList.add('hidden');
  setEvent('A FRESH START', 'Your little snake is ready to see the city. Where to first?');
  updateUI();
}
function finishGame(won) {
  state.finished = true;
  state.won = won;
  state.pending = null;
  if (won) {
    setEvent('YOU DID IT', 'A tidy little fortune, made one square at a time.', '✳');
    setOverlay('Well, look at you.', `You built a <b>$${state.cash}</b> little empire.<br>Ready for another lap?`, 'PLAY AGAIN', '✳');
    showToast('City slicker status: unlocked.');
  } else {
    setEvent('END OF THE ROAD', `You finished with $${state.cash}. A new route might do the trick.`, '↻');
    setOverlay('The city can wait.', `You finished with <b>$${state.cash}</b>.<br>One more little run?`, 'TRY AGAIN', '↻');
  }
  updateUI();
}
function crash() {
  state.moves++;
  state.cash = Math.max(0, state.cash - 25);
  state.snake = [72, 71, 70];
  state.direction = 'right';
  state.pending = null;
  setEvent('A LITTLE DETOUR', 'Oops, tail trouble. You lost $25 and two moves finding your way back.', '↻');
  showToast('Tail trouble! −$25 and two moves.');
  state.moves = Math.min(MAX_MOVES, state.moves + 1);
  updateUI();
  if (state.cash >= GOAL) finishGame(true);
  else if (state.moves >= MAX_MOVES) finishGame(false);
}
function addCoin() {
  const blocked = new Set([...state.snake, ...propertyList.map((p) => p.id), ...stairPairs.flat()]);
  const options = [];
  for (let i = 0; i < SIZE * SIZE; i++) if (!blocked.has(i) && !state.coins.has(i)) options.push(i);
  if (options.length) state.coins.add(options[Math.floor(Math.random() * options.length)]);
}
function handleLanding(id) {
  if (state.coins.has(id)) {
    state.coins.delete(id);
    state.cash += 30;
    state.snake.push(state.snake[state.snake.length - 1]);
    addCoin();
    setEvent('LOOSE CHANGE!', 'A shiny little find. +$30 and a longer tail.', '✦');
    showToast('Coin collected! +$30');
  }
  const property = propertyAt(id);
  if (property && state.owned.has(id)) {
    state.cash += property.rent;
    setEvent('YOUR CORNER, YOUR RENT', `${property.name} paid you $${property.rent} in passing rent.`, '⌂');
    showToast(`${property.name} paid $${property.rent} rent.`);
  } else if (property) {
    state.pending = property;
    setEvent('A GOOD CORNER', `${property.name} is up for grabs. Fancy making it yours?`, '＋');
  }
}
function step(direction) {
  if (!state.started || state.finished || state.pending) return;
  if (state.direction && opposite[state.direction] === direction && state.snake.length > 1) {
    showToast('No U-turns — your tail is right there!');
    return;
  }
  state.direction = direction;
  const [dy, dx] = directions[direction];
  const head = state.snake[0];
  const row = Math.floor(head / SIZE) + dy;
  const col = head % SIZE + dx;
  if (row < 0 || row >= SIZE || col < 0 || col >= SIZE) return crash();
  let next = row * SIZE + col;
  const mate = stairMate(next);
  if (mate !== null) {
    next = mate;
    setEvent('STAIRWAY SHORTCUT', 'A hop, skip, and a jump across town. Nice.', '↗');
  }
  const eating = state.coins.has(next);
  const bodyToCheck = eating ? state.snake : state.snake.slice(0, -1);
  if (bodyToCheck.includes(next)) return crash();
  state.snake.unshift(next);
  if (!eating) state.snake.pop();
  state.moves++;
  handleLanding(next);
  updateUI();
  if (state.cash >= GOAL) finishGame(true);
  else if (state.moves >= MAX_MOVES && !state.pending) finishGame(false);
}
function resolvePurchase(buy) {
  if (!state.pending || state.finished) return;
  const p = state.pending;
  state.pending = null;
  if (buy && state.cash >= p.price) {
    state.cash -= p.price;
    state.owned.add(p.id);
    setEvent('NEW DEED, WHO DIS?', `${p.name} is yours. Rent is $${p.rent} whenever you land here.`, '⌂');
    showToast(`${p.name} is yours!`);
  } else {
    setEvent('MAYBE NEXT TIME', `You left ${p.name} on the market. Keep your cash handy.`, '↗');
  }
  updateUI();
  if (state.cash >= GOAL) finishGame(true);
  else if (state.moves >= MAX_MOVES) finishGame(false);
}
function resetGame() {
  state = freshState();
  setEvent('A FRESH START', 'Your little snake is ready to see the city. Where to first?');
  $('start-overlay').classList.remove('hidden');
  setOverlay('Your city awaits.', 'Collect coins. Claim corners.<br>Try not to eat your own tail.', 'START YOUR RUN');
  updateUI();
}

setupBoard();
state = freshState();
updateUI();
$('start-button').addEventListener('click', startGame);
$('buy-button').addEventListener('click', () => resolvePurchase(true));
$('pass-button').addEventListener('click', () => resolvePurchase(false));
$('restart-button').addEventListener('click', resetGame);
document.querySelectorAll('.dpad-button').forEach((button) => {
  button.addEventListener('click', () => step(button.dataset.dir));
});
document.addEventListener('keydown', (event) => {
  const keyMap = { ArrowUp: 'up', ArrowDown: 'down', ArrowLeft: 'left', ArrowRight: 'right', w: 'up', s: 'down', a: 'left', d: 'right' };
  if (keyMap[event.key]) {
    event.preventDefault();
    step(keyMap[event.key]);
  }
  if (event.key === 'Escape') $('help-modal').classList.add('hidden');
});
$('help-button').addEventListener('click', () => $('help-modal').classList.remove('hidden'));
$('close-help').addEventListener('click', () => $('help-modal').classList.add('hidden'));
$('got-it-button').addEventListener('click', () => $('help-modal').classList.add('hidden'));
$('help-modal').addEventListener('click', (event) => { if (event.target === $('help-modal')) $('help-modal').classList.add('hidden'); });
$('sound-toggle').addEventListener('click', (event) => {
  const button = event.currentTarget;
  button.classList.toggle('sound-on');
  button.title = button.classList.contains('sound-on') ? 'Sound effects are not enabled' : 'Sound is off';
  showToast(button.classList.contains('sound-on') ? 'Sound effects coming soon.' : 'Sound is off.');
});

